<?php $title = 'Pontos e brindes — Felito'; $redemptionStatus = ['pending' => 'Aguardando equipe', 'delivered' => 'Entregue', 'cancelled' => 'Cancelado']; ?>
<section class="content-layout"><div class="page-heading"><div><div class="eyebrow"><span class="dot"></span>Fidelidade Felito</div><h1><?= (int) $balance ?> pontos</h1><p>Você acumula pontos quando uma encomenda é marcada como entregue.</p></div></div>
  <section class="panel manager-list-panel"><div class="section-heading compact-heading"><div><div class="eyebrow">Recompensas</div><h2>Troque pontos por brindes</h2></div></div><?php if (!$rewards): ?><div class="empty-state small-empty"><p>A equipe está preparando as recompensas.</p></div><?php else: ?><div class="reward-grid"><?php foreach ($rewards as $reward): ?><article class="panel reward-card"><span class="eyebrow"><?= (int) $reward['points_cost'] ?> pontos</span><h3><?= e($reward['name']) ?></h3><p><?= e($reward['description']) ?></p><form method="post"><?= csrfField() ?><input type="hidden" name="reward_id" value="<?= (int) $reward['id'] ?>"><button class="button button-primary" type="submit"<?= $balance < $reward['points_cost'] ? ' disabled' : '' ?>>Solicitar brinde</button></form></article><?php endforeach ?></div><?php endif ?></section>
  <div class="manager-grid"><section class="panel manager-list-panel"><h2>Seus pontos</h2><?php if (!$movements): ?><p class="muted-copy">Os pontos aparecem aqui depois da primeira entrega.</p><?php else: ?><div class="movement-list"><?php foreach ($movements as $movement): ?><article class="movement-row"><div class="movement-copy"><strong><?= $movement['points_delta'] > 0 ? '+' : '' ?><?= (int) $movement['points_delta'] ?> pontos</strong><p><?= e($movement['reason']) ?></p><small><?= e(localDateTime($movement['created_at'])) ?></small></div></article><?php endforeach ?></div><?php endif ?></section><section class="panel manager-list-panel"><h2>Resgates</h2><?php if (!$redemptions): ?><p class="muted-copy">Nenhum brinde solicitado.</p><?php else: ?><div class="movement-list"><?php foreach ($redemptions as $redemption): ?><article class="movement-row"><div class="movement-copy"><strong><?= e($redemption['reward_name']) ?> · <?= e($redemptionStatus[$redemption['status']] ?? $redemption['status']) ?></strong><small><?= e(localDateTime($redemption['created_at'])) ?></small></div></article><?php endforeach ?></div><?php endif ?></section></div>
</section>
